class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode curr = head;
        while (curr != null && curr.next != null) {
            if (curr.val == curr.next.val) {
                curr.next = curr.next.next;
            } else {
                curr = curr.next;
            }
        }
        return head;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode sentinel = new ListNode(0);
        ListNode tail = sentinel;
        ListNode read = head;

        while (read != null) {
            tail.next = read;
            tail = read;
            int value = read.val;
            while (read != null && read.val == value) {
                read = read.next;
            }
        }

        tail.next = null;
        return sentinel.next;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        head.next = deleteDuplicates(head.next);
        return head.val == head.next.val ? head.next : head;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        boolean first = true;
        int last = 0;
        ListNode read = head;

        while (read != null) {
            if (first || read.val != last) {
                tail.next = new ListNode(read.val);
                tail = tail.next;
                last = read.val;
                first = false;
            }
            read = read.next;
        }
        return dummy.next;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        if (head == null) {
            return null;
        }

        ListNode write = head;
        ListNode read = head.next;
        int last = head.val;

        while (read != null) {
            if (read.val != last) {
                write = write.next;
                write.val = read.val;
                last = read.val;
            }
            read = read.next;
        }

        write.next = null;
        return head;
    }
}
